search.query:
| inputlookup cmdb_assets.csv | makemv tokenizer="([^
]+)" ip | makemv tokenizer="([^
]+)" vendor | makemv tokenizer="([^
]+)" app_id | makemv tokenizer="([^
]+)" appname | search cmdb_status="$status$" cmdb_class="$envc$" $cat$ | mvexpand ip | join type=left ip [search index=rapid7 sourcetype=rapid7:vm:asset earliest=-5h | stats max(last_assessed_epoch) as last_assessed latest(hostname) as r7_hostname latest(os) as r7_os max(vuln_critical) as critical max(vuln_severe) as severe max(risk_score) as risk by ip] | lookup rapid7_host_context.csv host OUTPUT env AS r7_site_env | lookup rapid7_host_context.csv ip OUTPUTNEW env AS r7_site_env | stats values(ip) as ip values(vendor) as vendor values(app_id) as app_id values(appname) as appname first(device_category) as device_category first(va_scannable) as va_scannable first(cmdb_status) as cmdb_status first(cmdb_env) as cmdb_env first(cmdb_class) as cmdb_class max(last_assessed) as last_assessed values(r7_hostname) as r7_hostname values(r7_os) as r7_os max(critical) as critical max(severe) as severe max(risk) as risk values(r7_site_env) as r7_site_env by host | eval days_since=round((now()-last_assessed)/86400,0) | eval mapping_status=case( isnotnull(last_assessed) AND days_since<=30, "1 Mapped - assessed 30d", isnotnull(last_assessed), "2 Mapped - stale >30d", isnotnull(r7_site_env), "3 Site only - never scanned", true(), "4 Not in Rapid7") | eval kpi_group=case( in(device_category,"SERVER","VENDOR_APPLIANCE"), "Server", device_category="NETWORK", "Network", device_category="HYPERVISOR", "Hypervisor", true(), "Out of scope") | eval last_assessed_date=strftime(last_assessed,"%F") | fields host device_category kpi_group va_scannable cmdb_status cmdb_env cmdb_class vendor app_id appname ip r7_hostname r7_os r7_site_env last_assessed last_assessed_date days_since critical severe risk mapping_status
